package com.badrulamin.University_Management.service;
import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.AdmissionCampaign; import com.badrulamin.University_Management.repository.AdmissionCampaignRepository; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service;  import java.util.List;  @Service public class AdmissionCampaignService {      private final AdmissionCampaignRepository admissionCampaignRepository;      public AdmissionCampaignService(AdmissionCampaignRepository admissionCampaignRepository) {         this.admissionCampaignRepository = admissionCampaignRepository;     }      public Page<AdmissionCampaign> findAll(Pageable pageable) {         return admissionCampaignRepository.findAll(pageable);     }      public AdmissionCampaign findById(Long id) {         return admissionCampaignRepository.findById(id).orElseThrow(() -> new ResourceNotFoundException("AdmissionCampaign", "id", id));     }      public AdmissionCampaign create(AdmissionCampaign campaign) {         return admissionCampaignRepository.save(campaign);     }      public AdmissionCampaign update(Long id, AdmissionCampaign campaign) {         AdmissionCampaign existing = admissionCampaignRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("AdmissionCampaign", "id", id));         existing.setName(campaign.getName());         existing.setType(campaign.getType());         existing.setDescription(campaign.getDescription());         existing.setBudget(campaign.getBudget());         existing.setSpent(campaign.getSpent());         existing.setStartDate(campaign.getStartDate());         existing.setEndDate(campaign.getEndDate());         existing.setStatus(campaign.getStatus());         existing.setTargetAudience(campaign.getTargetAudience());         existing.setChannels(campaign.getChannels());         existing.setApplicationsGenerated(campaign.getApplicationsGenerated());         existing.setEnrollmentsConverted(campaign.getEnrollmentsConverted());         existing.setNotes(campaign.getNotes());         existing.setSession(campaign.getSession());         return admissionCampaignRepository.save(existing);     }      public void delete(Long id) {         admissionCampaignRepository.deleteById(id);     }      public long countByStatus(String status) {         return admissionCampaignRepository.countByStatus(status);     }      public List<AdmissionCampaign> findBySessionId(Long sessionId) {         return admissionCampaignRepository.findBySession_Id(sessionId);     } }